def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_times = {}
    results = []

    for op in ops:
        t = op[1]

        # Remove expired entries
        expired_keys = []
        for key in cache:
            if write_times[key] + ttl <= t:
                expired_keys.append(key)
        for key in expired_keys:
            del cache[key]
            del write_times[key]

        if op[0] == 'put':
            key = op[2]
            value = op[3]

            # Remove if already exists (to reorder)
            if key in cache:
                del cache[key]

            # Evict LRU if at capacity
            if len(cache) >= capacity:
                lru_key = next(iter(cache))
                del cache[lru_key]
                del write_times[lru_key]

            # Add the new entry
            cache[key] = value
            write_times[key] = t

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = value
                results.append(value)
            else:
                results.append(-1)

    return results

